// Meldung nötig? – prüft, ob SYNC 5 in den letzten 12 Stunden erfolgreich durchgelaufen ist.
// SYNC 5 läuft nachts, dieser Check knapp 4 Stunden später (beide im selben Zeitplan der Instanz).
const test = $('Testlauf (manuell)').isExecuted;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.matrix_user_id) continue;
  const stand = j.letzter_erfolg ? new Date(j.letzter_erfolg) : null;
  const stunden = stand ? (Date.now() - stand.getTime()) / 3600000 : null;
  if (!test && stunden !== null && stunden < 12) continue;
  const letzter = j.letzter_erfolg_text || 'noch keiner vermerkt';
  const zeilenText = [
    'Abgleich Papierkram – timeBuzzer' + (test ? ' (Testlauf)' : '') + ':',
    '',
    (test ? 'Testnachricht. Im echten Fall steht hier: ' : '') + 'Der nächtliche Abgleich (SYNC 5) ist nicht erfolgreich durchgelaufen.',
    '',
    'Letzter erfolgreicher Lauf: ' + letzter,
    '',
    'Was das bedeutet:',
    'Neue oder geänderte Kunden und Projekte aus Papierkram sind in timeBuzzer eventuell noch nicht angekommen. Die Fehlerdetails stehen in n8n bei SYNC 5 unter Ausführungen.'
  ];
  const html = '<strong>Abgleich Papierkram – timeBuzzer' + (test ? ' (Testlauf)' : '') + ':</strong><br>' +
    (test ? 'Testnachricht. Im echten Fall steht hier: ' : '') + 'Der nächtliche Abgleich (SYNC 5) ist nicht erfolgreich durchgelaufen.<br><br>' +
    'Letzter erfolgreicher Lauf: ' + letzter + '<br><br>' +
    '<strong>Was das bedeutet:</strong><br>' +
    'Neue oder geänderte Kunden und Projekte aus Papierkram sind in timeBuzzer eventuell noch nicht angekommen. Die Fehlerdetails stehen in n8n bei SYNC 5 unter Ausführungen.';
  out.push({ json: { user_id: j.matrix_user_id, text: zeilenText.join('\n'), html: html } });
}
return out;
